def is_majority(arr, n, element):
    """
    Return True if `element` is the majority element in the sorted array `arr`
    of length `n`, meaning it occurs more than n/2 times.
    """
    if n <= 0:
        return False

    def lower_bound(target):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound(target, start=0):
        lo, hi = start, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    left = lower_bound(element)
    if left == n or arr[left] != element:
        return False

    right = upper_bound(element, left + 1) - 1
    count = right - left + 1

    return 2 * count > n


assert is_majority([1, 2, 3, 3, 3, 3, 10], 7, 3) == True
