def magic_square_test(matrix):
    if not matrix:
        return False

    n = len(matrix)
    if len(matrix[0]) != n:
        return False

    for row in matrix:
        if len(row) != n:
            return False

    magic_sum = sum(matrix[0])

    for row in matrix:
        if sum(row) != magic_sum:
            return False

    for col in range(n):
        if sum(row[col] for row in matrix) != magic_sum:
            return False

    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False

    if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
        return False

    return True

