def is_samepatterns(values, patterns):
    """
    Return True if `values` follows the same equality pattern as `patterns`.

    A valid match requires:
    - Same length.
    - If two pattern entries are equal, the corresponding value entries must be equal.
    - If two pattern entries are different, the corresponding value entries must be different.
    """
    if len(values) != len(patterns):
        return False

    value_to_pattern = {}
    pattern_to_value = {}

    for value, pattern in zip(values, patterns):
        if value in value_to_pattern:
            if value_to_pattern[value] != pattern:
                return False
        else:
            value_to_pattern[value] = pattern

        if pattern in pattern_to_value:
            if pattern_to_value[pattern] != value:
                return False
        else:
            pattern_to_value[pattern] = value

    return True


if __name__ == "__main__":
