class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def get_substrings(x: str):
            parts = [("", 0)]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    parts.append((x[i:j], j - i))
            return parts

        s_parts = get_substrings(s)
        t_parts = get_substrings(t)

        ans = 0
        max_possible = len(s) + len(t)

        for a, a_len in s_parts:
            for b, b_len in t_parts:
                total_len = a_len + b_len
                if total_len <= ans:
                    continue

                candidate = a + b
                if candidate == candidate[::-1]:
                    ans = total_len
                    if ans == max_possible:
                        return ans

        return ans
