class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []

        limit = max(groups)
        inf = len(elements) + 1

        first_index = [inf] * (limit + 1)
        for idx, value in enumerate(elements):
            if value <= limit and idx < first_index[value]:
                first_index[value] = idx

        best_index = [inf] * (limit + 1)

        for value in range(1, limit + 1):
            idx = first_index[value]
            if idx != inf:
                for multiple in range(value, limit + 1, value):
                    if idx < best_index[multiple]:
                        best_index[multiple] = idx

        return [
            best_index[group] if best_index[group] != inf else -1
            for group in groups
        ]
