class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        ans = total_k

        # Only values actually present can be converted into k.
        for v in set(nums):
            if v == k:
                continue

            cur = 0
            best = 0

            for num in nums:
                if num == v:
                    cur += 1
                elif num == k:
                    cur -= 1

                if cur > best:
                    best = cur
                elif cur < 0:
                    cur = 0

            ans = max(ans, total_k + best)

        return ans
